// Simulación didáctica (inventada) del bucle de mensajes de una ventana.
// El tiempo es virtual: cada mensaje llega en un instante y cada manejador tarda lo que dice "costo".
const cola = [];
const publicar = (t, tipo, costo = 1) => cola.push({ t, tipo, costo });

function ProcVentana(msg) {
  switch (msg.tipo) {
    case "CLIC_ETIQUETA":   return "imprime etiqueta";
    case "CLIC_INFORME":    return "ejecuta el informe de stock";
    case "REPINTAR":        return "dibuja la ventana";
    case "CERRAR":          return "cierra";
    default:                return "procesamiento por defecto";
  }
}

function bucle(titulo) {
  let reloj = 0;
  console.log("== " + titulo);
  cola.sort((a, b) => a.t - b.t);
  while (cola.length) {                 // GetMessage: saca el primero
    const m = cola.shift();
    reloj = Math.max(reloj, m.t);       // si estaba vacía, espera a que llegue
    const espera = reloj - m.t;
    const que = ProcVentana(m);         // DispatchMessage: llama al procedimiento
    reloj += m.costo;
    console.log(`t=${String(m.t).padStart(2)} ${m.tipo.padEnd(14)} espera=${String(espera).padStart(2)} -> ${que}`);
  }
}

// Caso 1: el informe se calcula en un hilo aparte, el manejador solo lo lanza (costo 1).
publicar(0, "CLIC_INFORME", 1); publicar(1, "REPINTAR", 1); publicar(2, "CLIC_ETIQUETA", 1); publicar(3, "REPINTAR", 1);
bucle("informe en otro hilo");

// Caso 2: el informe se calcula en el mismo hilo que el bucle (costo 8).
publicar(0, "CLIC_INFORME", 8); publicar(1, "REPINTAR", 1); publicar(2, "CLIC_ETIQUETA", 1); publicar(3, "REPINTAR", 1);
bucle("informe en el hilo de la interfaz");
